package org.opensourcepingpong.organization;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="user_organization_roles") public class UserOrganizationRole { @Id private UUID id; @Column(name="user_id") private UUID userId; @Column(name="role_id") private UUID roleId; @Column(name="granted_by") private UUID grantedBy; @Column(name="granted_at") private Instant grantedAt; @Column(name="revoked_at") private Instant revokedAt; protected UserOrganizationRole(){} public UserOrganizationRole(UUID userId,UUID roleId,UUID by){id=UUID.randomUUID();this.userId=userId;this.roleId=roleId;grantedBy=by;grantedAt=Instant.now();} public UUID getUserId(){return userId;} public UUID getRoleId(){return roleId;} public Instant getRevokedAt(){return revokedAt;} }
